local a={}local b='sRawName'local c=require(GetScriptDirectory()..'/FuncLib/systems/localization')local d=require(GetScriptDirectory()..'/FuncLib/systems/custom_loader')a['tItemNameList']=require(GetScriptDirectory()..'/FuncLib/data/item_names')a['tHeroNameList']=require(GetScriptDirectory()..'/FuncLib/data/hero_names')local e={}for f,g in pairs(a['tItemNameList'])do e[g['sRawName']]=g['sCnName']end;function a.GetItemCnName(h)return e[h]or"未定义:"..h end;function a.GetLocalName(i)local j=a['tHeroNameList'][i:GetUnitName()]if j~=nil then return j[b]end end;function a.GetNormName(i)local j=a['tHeroNameList'][i:GetUnitName()]return j~=nil and j['sNormName']or string.sub(i:GetUnitName(),10)end;local k=require(GetScriptDirectory()..'/FuncLib/data/chat_table')local l={}for m=1,#k do local n=k[m][1]for f,o in pairs(n)do local p=l[o]if p==nil then l[o]=m else for f,q in pairs(k[m][2])do table.insert(k[p][2],q)end;for f,q in pairs(k[m][3])do table.insert(k[p][3],q)end end end end;function a.GetChatStringTableIndex(r)return l[r]or-1 end;function a.GetChatTableString(s,t)local u=k[s][t and 3 or 2]return u[RandomInt(1,#u)]end;function a.GetReplyString(r,t)if not a.AllowTrashTalk(t)then return nil end;local v=nil;if d.Localization=='zh'then local s=a.GetChatStringTableIndex(r)if s~=-1 then v=a.GetChatTableString(s,t)else v=a.GetCheaterReplyString(r)if v==nil then v=a.GetRepeatString(r)end end end;if v==nil or RandomInt(1,100)>90 then local w=c.Get('random_responses')v=w[RandomInt(1,#w)]end;return v end;function a.AllowTrashTalk(t)local x=d.Trash_Talk_Level;return d.Allow_Trash_Talk and(not t and(x==nil or x>=2)or t and(x==nil or x>=1))end;function a.GetCheaterReplyString(r)return string.byte(r,1)==string.byte('-',1)and"cheater"or nil end;function a.GetRepeatString(r)local y={"你们","你","我","吗？","吗","吧","？"}for f,z in ipairs(y)do if r==z then return nil end end;local A=r;if r:find("我是你")then return r:gsub("我是你","我才是你")end;local B={"sb","SB","智障","弱智","脑残","脑瘫","猪","傻","菜","笨","蠢"}for